     * @var bool
     */
    private bool $hide_fastlane_watermark = \false;
    public function __construct(\WooCommerce\PayPalCommerce\WcGateway\Helper\ConnectionState $connection_state, \WooCommerce\PayPalCommerce\Settings\Data\SettingsProvider $settings_provider, \WooCommerce\PayPalCommerce\ApiClient\Helper\DccApplies $dcc_applies, \WooCommerce\PayPalCommerce\WcGateway\Helper\DCCProductStatus $dcc_status, string $store_country)
    {
    }
    /**
     * Marks the current settings as "outdated". The next time a setting is accessed
     * it will be resolved using the current settings.
     *
     * @return void
     */
    public function refresh(): void
    {
    }
    /**
     * Ensures the internally cached flags correctly reflect the current settings.
     *
     * @return void
     */
    private function ensure_resolved_values(): void
    {
    }
    /**
     * Refreshes the internal gateway configuration based on the current settings.
     */
    private function resolve(): void
    {
    }
